import { existsSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

import { defineConfig } from 'vite'
import { viteStaticCopy } from 'vite-plugin-static-copy'

const __dirname = dirname(fileURLToPath(import.meta.url))

/**
 * Generated by `scripts/build-wasm.mjs` (wasm-bindgen --target web). The copy
 * `src` must be a root-relative POSIX glob, so keep both an absolute path (for
 * the existence check) and a relative one (for viteStaticCopy).
 */
const WASM_SRC_ABS = resolve(
  __dirname,
  'wasm',
  'pkg',
  'acad_rust_converter_bg.wasm'
)
const WASM_SRC_REL = 'wasm/pkg/acad_rust_converter_bg.wasm'
/** Deployed next to the worker; the worker fetches it via `self.location`. */
const WASM_OUT_NAME = 'acad-rust_bg.wasm'
const WORKER_OUT_NAME = 'acad-rust-parser-worker.js'

if (!existsSync(WASM_SRC_ABS)) {
  throw new Error(
    `[acad-rust-converter] Missing WASM artifact:\n  ${WASM_SRC_ABS}\n` +
      'Run `pnpm build:wasm` first (requires the Rust toolchain: cargo + ' +
      'wasm32-unknown-unknown + wasm-bindgen-cli 0.2.126).'
  )
}

/**
 * Worker bundle: `src/worker.ts` + the inlined wasm-bindgen glue, emitted as a
 * single classic (IIFE) worker script so hosts deploy exactly two files —
 * `acad-rust-parser-worker.js` and its sibling `acad-rust_bg.wasm`.
 *
 * The WASM is NOT inlined; the worker fetches the sibling at runtime, matching
 * the LibreDWG deployment model this package replaces.
 */
export default defineConfig({
  build: {
    outDir: 'dist',
    // The main config owns `emptyOutDir`; this runs second and only adds files.
    emptyOutDir: false,
    lib: {
      entry: resolve(__dirname, 'src', 'worker.ts'),
      formats: ['iife'],
      name: 'AcadRustParserWorker',
      fileName: () => WORKER_OUT_NAME
    },
    minify: true
  },
  plugins: [
    viteStaticCopy({
      targets: [
        {
          src: WASM_SRC_REL,
          dest: '.',
          // stripBase flattens `wasm/pkg/…` to the dist root, then `name`
          // renames it to the deployed asset filename.
          rename: { name: WASM_OUT_NAME, stripBase: true }
        }
      ]
    })
  ]
})
